const cfg = $('Configuracao MonitorHub').first().json;
const payload = $input.first()?.json || {};
const now = new Date().toISOString();
const records = Array.isArray(payload?.results)
  ? payload.results
  : Array.isArray(payload?.items)
    ? payload.items
    : Array.isArray(payload?.data?.results)
      ? payload.data.results
      : [];

function toNumber(value) {
  if (value === null || value === undefined || value === '') return null;
  if (typeof value === 'number') return Number.isFinite(value) ? value : null;
  const raw = String(value).replace(/\s/g, '').replace(/R\$/gi, '').replace(/[^0-9,.-]/g, '');
  if (!raw) return null;
  const hasComma = raw.includes(',');
  const hasDot = raw.includes('.');
  let normalized = raw;
  if (hasComma && hasDot) normalized = raw.lastIndexOf(',') > raw.lastIndexOf('.') ? raw.replace(/\./g, '').replace(',', '.') : raw.replace(/,/g, '');
  else if (hasComma) normalized = raw.replace(',', '.');
  const number = Number(normalized);
  return Number.isFinite(number) ? number : null;
}

function percentile(sorted, ratio) {
  if (!sorted.length) return null;
  const index = Math.min(sorted.length - 1, Math.max(0, Math.round((sorted.length - 1) * ratio)));
  return sorted[index];
}

const prices = records
  .map((item) => toNumber(item.price))
  .filter((price) => price !== null && price > 0)
  .sort((a, b) => a - b);
const p25 = percentile(prices, 0.25);
const median = percentile(prices, 0.5);

const products = records.map((item) => {
  const price = toNumber(item.price);
  let opportunityScore = 50;
  if (price !== null && median) {
    const discountVsMedian = ((median - price) / median) * 100;
    opportunityScore = Math.max(1, Math.min(100, Math.round(55 + discountVsMedian * 1.2)));
  }
  if (price !== null && p25 && price <= p25) opportunityScore = Math.max(opportunityScore, 82);

  return {
    id: item.id,
    title: item.title,
    price,
    currency: item.currency_id || cfg.currency || 'BRL',
    url: item.permalink,
    image: item.secure_thumbnail || item.thumbnail || item.pictures?.[0]?.url || '',
    seller: item.seller?.nickname || String(item.seller?.id || ''),
    availability: item.available_quantity ? `${item.available_quantity} disponivel` : String(item.condition || ''),
    source: 'Mercado Livre',
    sourceKind: 'mercadolivre',
    query: cfg.query,
    fetchedAt: now,
    opportunityScore,
    notes: opportunityScore >= 82 ? 'Preco abaixo do primeiro quartil da busca.' : 'Item coletado pelo n8n para acompanhamento.'
  };
}).filter((item) => item.id && item.title && item.opportunityScore >= Number(cfg.minOpportunityScore || 0));

products.sort((a, b) => (b.opportunityScore || 0) - (a.opportunityScore || 0));

const errors = [];
if (!records.length) {
  const detail = payload?.message || payload?.error || payload?.statusMessage || 'sem itens retornados';
  errors.push(`n8n: Mercado Livre nao retornou produtos para "${cfg.query}" (${detail}).`);
}

return [{
  json: {
    runId: $execution?.id || `manual-${Date.now()}`,
    source: 'n8n',
    sourceName: 'Mercado Livre',
    query: cfg.query,
    currency: cfg.currency || 'BRL',
    products,
    errors,
    fetchedAt: now,
    monitorHubEndpoint: cfg.monitorHubEndpoint,
    monitorHubIngestToken: cfg.monitorHubIngestToken
  }
}];
